const parseCSVText = (text) => {
  if (!text) return [];
  const lines = String(text).replace(/\r/g, '').split('\n').filter((line) => line.trim().length > 0);
  if (lines.length === 0) return [];

  const parseLine = (line) => {
    const out = [];
    let cur = '';
    let inQuotes = false;
    for (let i = 0; i < line.length; i += 1) {
      const ch = line[i];
      if (ch === '"' && line[i + 1] === '"') {
        cur += '"';
        i += 1;
      } else if (ch === '"') {
        inQuotes = !inQuotes;
      } else if (ch === ',' && !inQuotes) {
        out.push(cur);
        cur = '';
      } else {
        cur += ch;
      }
    }
    out.push(cur);
    return out.map((value) => value.trim());
  };

  const headers = parseLine(lines[0]).map((h) => h.toLowerCase());
  return lines.slice(1).map((line) => {
    const cols = parseLine(line);
    const obj = {};
    headers.forEach((h, idx) => {
      obj[h] = cols[idx] ?? '';
    });
    return obj;
  }).filter((row) => Object.values(row).some((value) => String(value || '').trim().length > 0));
};

const requestStatusColor = (status) => {
  const s = String(status || '').toUpperCase();
  if (s === 'APPROVED') return 'bg-emerald-50 text-emerald-700 border-emerald-200';
  if (s === 'IN PROGRESS' || s === 'IN_PROGRESS' || s === 'INPROGRESS') return 'bg-blue-50 text-blue-700 border-blue-200';
  if (s === 'DECLINED' || s === 'REJECTED') return 'bg-rose-50 text-rose-700 border-rose-200';
  if (s === 'SUBMITTED' || s === 'PENDING') return 'bg-amber-50 text-amber-700 border-amber-200';
  return 'bg-gray-50 text-gray-600 border-gray-200';
};

const PriorityBadge = ({ priority }) => {
  const p = String(priority || 'MEDIUM').toUpperCase();
  const classes = p === 'URGENT'
    ? 'bg-rose-100 text-rose-700 border-rose-200'
    : p === 'HIGH'
      ? 'bg-orange-100 text-orange-700 border-orange-200'
      : p === 'MEDIUM'
        ? 'bg-amber-100 text-amber-700 border-amber-200'
        : 'bg-blue-100 text-blue-700 border-blue-200';
  return (
    <span className={`inline-flex items-center px-2.5 py-1 rounded-full text-xs font-semibold border ${classes}`}>
      {p}
    </span>
  );
};

// â”€â”€ Stat card â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
function StatCard({ label, value, sub, accent, icon, onClick }) {
  const accents = {
    blue: 'from-blue-50 to-indigo-50 border-blue-100',
    green: 'from-emerald-50 to-teal-50 border-emerald-100',
    red: 'from-rose-50 to-pink-50 border-rose-100',
    indigo: 'from-indigo-50 to-purple-50 border-indigo-100',
    amber: 'from-amber-50 to-yellow-50 border-amber-100',
  };
  const c = accents[accent] || accents.blue;
  return (
    <div
      onClick={onClick}
      className={`glass-surface rounded-xl p-4 xs:p-5 sm:p-6 flex items-start gap-3 sm:gap-4 border-l-4 overflow-hidden relative group transition-all hover:scale-[1.02] ${onClick ? 'cursor-pointer hover:ring-2 hover:ring-blue-100' : ''}`}
      role={onClick ? 'button' : undefined}
      tabIndex={onClick ? 0 : -1}
      onKeyDown={onClick ? (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); onClick(); } } : undefined}
    >
      <div className={`absolute inset-0 bg-gradient-to-br ${c} opacity-90`} />
      <div className="relative z-10 w-10 h-10 sm:w-12 sm:h-12 rounded-xl glass-mirror flex items-center justify-center text-blue-700 shadow-lg bg-white/80 border border-blue-100 shrink-0">
        {icon}
      </div>
      <div className="relative z-10 min-w-0">
        <div className="text-2xl xs:text-3xl font-black text-gray-900 tracking-tight truncate">{value}</div>
        <div className="text-[10px] xs:text-xs sm:text-sm font-bold text-gray-700 uppercase tracking-wider mt-1 truncate">{label}</div>
        {sub && <div className="hidden xs:block text-xs text-gray-600 mt-1 font-medium truncate">{sub}</div>}
      </div>
    </div>
  );
}

// â”€â”€ Section header â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
function SectionHeader({ title, count, action }) {
  return (
    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 20 }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
        <h2 style={{ fontSize: 20, fontWeight: 700, color: '#111827', margin: 0 }}>{title}</h2>
        {count !== undefined && (
          <span style={{ background: '#F3F4F6', color: '#6B7280', fontSize: 12, fontWeight: 600, padding: '2px 8px', borderRadius: 20 }}>{count}</span>
        )}
      </div>
      {action}
    </div>
  );
}

// â”€â”€ Table â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
// Centralized Popover (manager parity)
const FilterPopover = ({ isOpen, onClose, title, children, className = "", anchorRef = null, bodyClassName = "" }) => {
  const [position, setPosition] = useState({ top: 0, left: 0, width: null });

  useEffect(() => {
    if (!isOpen || !anchorRef?.current) return undefined;

    const updatePosition = () => {
      const rect = anchorRef.current?.getBoundingClientRect();
      if (!rect) return;
      const estimatedWidth = rect.width >= 700 ? rect.width : 760;
      const maxLeft = Math.max(16, window.innerWidth - estimatedWidth - 16);
      setPosition({
        top: rect.bottom + 8,
        left: Math.min(rect.left, maxLeft),
        width: rect.width,
      });
    };

    updatePosition();
    window.addEventListener('resize', updatePosition);
    window.addEventListener('scroll', updatePosition, true);

    return () => {
      window.removeEventListener('resize', updatePosition);
      window.removeEventListener('scroll', updatePosition, true);
    };
  }, [anchorRef, isOpen]);

  if (!isOpen) return null;
  if (anchorRef?.current && typeof document !== 'undefined') {
    return createPortal(
      <>
        <div className="fixed inset-0 z-[1190]" onClick={onClose} />
        <div
          className={`fixed z-[1200] glass-surface-strong rounded-xl min-w-[240px] animate-in fade-in zoom-in duration-200 ${className}`}
          style={{ top: position.top, left: position.left, minWidth: position.width || undefined }}
        >
          {title ? (
            <div className="flex items-center justify-between p-4 border-b border-gray-50">
              <span className="text-sm font-bold text-gray-900">{title}</span>
              <button onClick={onClose} className="p-1 hover:bg-gray-100 rounded-lg transition-colors">
                <X className="w-4 h-4 text-gray-400" />
              </button>
            </div>
          ) : null}
          <div className={bodyClassName || "max-h-[320px] overflow-y-auto p-2"}>
            {children}
          </div>
        </div>
      </>,
      document.body
    );
  }

  return (
    <>
      <div className="fixed inset-0 z-40" onClick={onClose} />
      <div className={`absolute top-full mt-2 left-0 z-50 glass-surface-strong rounded-xl min-w-[240px] animate-in fade-in zoom-in duration-200 ${className}`}>
        {title ? (
          <div className="flex items-center justify-between p-4 border-b border-gray-50">
            <span className="text-sm font-bold text-gray-900">{title}</span>
            <button onClick={onClose} className="p-1 hover:bg-gray-100 rounded-lg transition-colors">
              <X className="w-4 h-4 text-gray-400" />
            </button>
          </div>
        ) : null}
        <div className={bodyClassName || "max-h-[320px] overflow-y-auto p-2"}>
          {children}
        </div>
      </div>
    </>
  );
};

const FilterButton = ({ icon: Icon, label, active, count, onClick }) => (
  <button
    type="button"
    onClick={onClick}
    className={`inline-flex h-11 items-center gap-2 rounded-2xl border px-4 text-[15px] font-medium shadow-sm transition ${
      active
        ? 'border-blue-300 bg-blue-50 text-blue-700'
        : 'border-gray-300 bg-white text-gray-700 hover:bg-gray-50'
    }`}
  >
    {Icon ? <Icon className="h-4 w-4" /> : null}
    <span>{label}</span>
    {typeof count === 'number' && count > 0 ? <span className="text-[13px] font-semibold">({count})</span> : null}
    <ChevronDown className="h-4 w-4" />
  </button>
);

