  // â”€â”€ Helper Functions â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  const getCurrentUser = useCallback(() => {
    try {
      const stored = localStorage.getItem('user');
      return stored ? JSON.parse(stored) : null;
    } catch {
      return null;
    }
  }, []);

  const getCurrentUserId = useCallback(() => {
    const user = getCurrentUser();
    return user?.id || user?._id || null;
  }, [getCurrentUser]);

  const modalTechnicians = allWorkers;

  const isRestrictedRole = useCallback((role, companyName = '') => {
    const r = String(role || '').toLowerCase();
    const hasCompanyScope = Boolean(String(companyName || '').trim());
    if (hasCompanyScope && (r === 'client' || r === 'requestor')) {
      return false;
    }
    return r === 'client' || r === 'requestor';
  }, []);

  useEffect(() => {
    const userId = currentUser?._id || currentUser?.id;
    if (!userId) return;
    let cancelled = false;
    const loadSideData = async () => {
      try {
        const [noteRes, allNotificationsRes] = await Promise.all([
          api.get('/api/private-notes/me', { params: { scope: 'client-dashboard' } }),
          api.get('/api/notifications', { params: { limit: 100 } })
        ]);
        if (cancelled) return;
        const allNotifications = Array.isArray(allNotificationsRes?.data) ? allNotificationsRes.data : [];
        setPrivateNote(noteRes?.data?.content || '');
        setMentionNotifications(allNotifications.filter((entry) => String(entry?.type || '').toLowerCase() === 'mention').slice(0, 6));
        setDirectMessageNotifications(
          allNotifications.filter((entry) => String(entry?.type || '').toLowerCase().startsWith('direct_message'))
        );
      } catch (err) {
        console.error('Failed to load client dashboard side data', err);
      } finally {
        if (!cancelled) setNoteReady(true);
      }
    };

    loadSideData();
    const handleVisibilityRefresh = () => {
      if (typeof document !== 'undefined' && document.hidden) return;
      loadSideData();
    };
    if (typeof window !== 'undefined') window.addEventListener('focus', handleVisibilityRefresh);
    if (typeof document !== 'undefined') document.addEventListener('visibilitychange', handleVisibilityRefresh);
    return () => {
      cancelled = true;
      if (typeof window !== 'undefined') window.removeEventListener('focus', handleVisibilityRefresh);
      if (typeof document !== 'undefined') document.removeEventListener('visibilitychange', handleVisibilityRefresh);
    };
  }, [currentUser]);

