  const fetchIssues = useCallback(async (context = {}) => {
    try {
      const res = await api.get('/api/issues');
      const now = new Date();
      const fetched = (res.data || []).map(issue => {
        const diff = now - new Date(issue.createdAt);
        const hours = Math.floor(diff / 3600000);
        const time = hours > 24 ? `${Math.floor(hours / 24)}d ago` : hours > 0 ? `${hours}h ago` : 'Just now';
        const st = (issue.status || '').toUpperCase();
        const isCompleted = st.includes('COMPLETE') || st === 'CLOSED' || st === 'DONE' || st === 'RESOLVED';
        const dueDate = getIssueDueDateValue(issue);
        const parsedDueDate = dueDate ? new Date(dueDate) : null;
        const isPastDue = parsedDueDate && !Number.isNaN(parsedDueDate.getTime()) && parsedDueDate < now;
        const isOverdue = Boolean(isPastDue) || ((st === 'PENDING' || st.includes('PROGRESS')) && hours > 72);
        return { ...issue, time, overdue: !isCompleted && (issue.overdue ?? isOverdue) };
      }).sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
      const user = context.user || getCurrentUser();
      const userId = user?.id || user?._id || null;
      const companyName = user?.companyName || null;
      const propertyIds = (context.propertyIds || propertiesRef.current.map(p => p._id || p.id)).filter(Boolean).map(String);
      const assetIds = (context.assetIds || assetsRef.current.map(a => a._id || a.id)).filter(Boolean).map(String);
      const scoped = isRestrictedRole(user?.role, companyName)
        ? filterIssuesForUser(fetched, userId, propertyIds, assetIds, companyName)
        : fetched;

      setIssues(scoped);
      setAllIssues(scoped);
      const counts = { Open: 0, Pending: 0, 'In Progress': 0, Completed: 0, Overdue: 0 };
      scoped.forEach(issue => {
        const st = (issue.status || '').toLowerCase().replace(/_/g, ' ');
        const isCompleted = st.includes('complete') || st.includes('verified') || st === 'closed' || st === 'done' || st === 'resolved';
        if (st === 'open' || st.startsWith('open ') || st.includes('approved')) counts.Open++;
        else if (st.includes('pending')) counts.Pending++;
        else if (st.includes('progress')) counts['In Progress']++;
        else if (st.includes('complete') || st.includes('verified')) counts.Completed++;
        if (isIssueOverdue(issue)) counts.Overdue++;
      });
      setStatusCounts(counts);
    } catch {
      setIssues([]);
      setAllIssues([]);
    }
  }, [filterIssuesForUser, getCurrentUser, isRestrictedRole]);

  // Keep issues fresh for client progress tracking
  useEffect(() => {
    const refreshIssues = () => {
      if (typeof document !== 'undefined' && document.hidden) return;
      fetchIssues();
    };

    refreshIssues();
    const intervalId = window.setInterval(refreshIssues, 30000);
    if (typeof window !== 'undefined') window.addEventListener('focus', refreshIssues);
    if (typeof document !== 'undefined') document.addEventListener('visibilitychange', refreshIssues);
    return () => {
      window.clearInterval(intervalId);
      if (typeof window !== 'undefined') window.removeEventListener('focus', refreshIssues);
      if (typeof document !== 'undefined') document.removeEventListener('visibilitychange', refreshIssues);
    };
  }, [fetchIssues]);

