  const openDashboardStatusView = (statusKey) => {
    const normalized = String(statusKey || '').toUpperCase();

    setRequestSearchQuery('');
    setSelectedRequestLocations([]);
    setSelectedRequestAssets([]);
    setSelectedRequestAssignedTo([]);
    setRequestOpenPopover(null);

    setWorkOrderSearchQuery('');
    setSelectedWorkOrderPriorities([]);
    setSelectedWorkOrderLocations([]);
    setSelectedWorkOrderAssets([]);
    setSelectedWorkOrderAssignedTo([]);
    setWorkOrderOpenPopover(null);

    if (normalized === 'PENDING') {
      setSelectedRequestStatuses(['Pending']);
      setSelectedWorkOrderStatuses([]);
      setActiveTab('requests');
      return;
    }

    if (normalized === 'OPEN') {
      setSelectedRequestStatuses([]);
      setSelectedWorkOrderStatuses(['OPEN']);
      setActiveTab('workOrders');
      return;
    }

    if (normalized === 'IN PROGRESS') {
      setSelectedRequestStatuses([]);
      setSelectedWorkOrderStatuses(['IN PROGRESS']);
      setActiveTab('workOrders');
      return;
    }

    if (normalized === 'COMPLETED') {
      setSelectedRequestStatuses([]);
      setSelectedWorkOrderStatuses(['COMPLETED']);
      setActiveTab('workOrders');
      return;
    }

    if (normalized === 'OVERDUE') {
      setSelectedRequestStatuses([]);
      setSelectedWorkOrderStatuses(['OVERDUE']);
      setActiveTab('workOrders');
      return;
    }
  };

  const isRejectedRequest = (issue) => {
    const st = String(issue?.status || '').toUpperCase();
    return st === 'REJECTED' || st === 'DECLINED';
  };

  const isPmLinkedIssue = (issue) => {
    return Boolean(
      issue?.scheduleId ||
      issue?.parentScheduleId ||
      issue?.maintenanceScheduleId ||
      issue?.pmId ||
      issue?.pmInstanceId ||
      issue?.pmTrigger ||
      issue?.preventiveMaintenanceName ||
      issue?.scheduleName ||
      issue?.pmName
    );
  };

  const isApprovedWorkOrder = (issue) => {
    const st = String(issue?.status || '').toUpperCase();
    const hasWorkOrderRef = !!(issue?.workOrderId || issue?.workOrder || issue?.workOrderNumber || issue?.workOrderNo || issue?.workOrderCode || issue?.workOrderRef);
    return Boolean(issue?.approved)
      || hasWorkOrderRef
      || isPmLinkedIssue(issue)
      || st === 'APPROVED'
      || st === 'OPEN'
      || st.includes('IN PROGRESS')
      || st.includes('COMPLETE');
  };

  const getPmWorkOrderOccurrenceKey = (issue) => {
    if (!isPmLinkedIssue(issue)) return '';
    const scheduleKey = String(
      issue?.parentScheduleId ||
      issue?.maintenanceScheduleId ||
      issue?.scheduleId ||
      issue?.pmId ||
      issue?.pmTrigger ||
      issue?.preventiveMaintenanceName ||
      ''
    ).trim().toLowerCase();
    const due = normalizeDate(issue?.dueDate || issue?.fixDeadline || issue?.createdAt);
    const dueKey = due ? due.toISOString().slice(0, 10) : '';
    const occurrenceKey = String(
      issue?.pmOccurrenceKey ||
      issue?.pmInstanceId ||
      issue?.pmInstanceNumber ||
      dueKey ||
      issue?.title ||
      ''
    ).trim().toLowerCase();
    return scheduleKey && occurrenceKey ? `${scheduleKey}:${occurrenceKey}` : '';
  };

  const dedupePmWorkOrders = (items = []) => {
    const seen = new Set();
    return (items || []).filter((issue) => {
      const key = getPmWorkOrderOccurrenceKey(issue);
      if (!key) return true;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
  };

  const isRequestRecord = (issue) => {
    if (!issue || isPmLinkedIssue(issue)) return false;
    const st = String(issue?.status || '').toUpperCase();
    return Boolean(
      issue?.requestorId
      || issue?.requestorName
      || issue?.submittedAt
      || issue?.submissionType
      || issue?.approved !== undefined
      || issue?.rejected !== undefined
      || st === 'SUBMITTED'
      || st === 'APPROVED'
      || st === 'DECLINED'
      || st === 'REJECTED'
      || st === 'PENDING'
    );
  };

  const isRequestIssue = (issue) => {
    if (!issue || isRejectedRequest(issue)) return false;
    return isRequestRecord(issue) || !isApprovedWorkOrder(issue);
  };

  const doesIssueBelongToCurrentUser = React.useCallback((issue) => {
    if (!issue) return false;

    const currentIds = Array.from(new Set([
      currentUser?._id,
      currentUser?.id,
      currentUser?.userId,
      currentUser?.email,
    ].filter(Boolean).map((value) => String(value).trim().toLowerCase())));

    const currentNames = Array.from(new Set([
      currentUser?.name,
      currentUser?.fullName,
      currentUser?.username,
      userName,
    ].filter(Boolean).map((value) => String(value).trim().toLowerCase())));

    const matchesPerson = (value) => {
      if (!value && value !== 0) return false;
      if (Array.isArray(value)) return value.some(matchesPerson);
      if (typeof value === 'object') {
        return matchesPerson(value._id)
          || matchesPerson(value.id)
          || matchesPerson(value.userId)
          || matchesPerson(value.email)
          || matchesPerson(value.name)
          || matchesPerson(value.fullName);
      }

      const normalized = String(value).trim().toLowerCase();
      if (!normalized) return false;
      return currentIds.includes(normalized) || currentNames.includes(normalized);
    };

    const resolvedAssignedName = String(getAssignedName(issue) || '').trim().toLowerCase();
    return (
      matchesPerson(issue.assignedTo)
      || matchesPerson(issue.assignees)
      || matchesPerson(issue.additionalResponsibleWorkers)
      || matchesPerson(issue.primaryWorker)
      || (resolvedAssignedName && currentNames.includes(resolvedAssignedName))
    );
  }, [currentUser, getAssignedName, userName]);

  const pendingRequests = allIssues.filter((issue) => !isPmLinkedIssue(issue) && isRequestIssue(issue));
  const combinedOpen = (statusCounts.open || statusCounts.Open || 0) + (maintenanceCounts.open || maintenanceCounts.Open || 0);
  const combinedPending = pendingRequests.filter((request) => getRequestDisplayState(request).statusLabel === 'Pending').length;
  const combinedInProgress = (statusCounts.inProgress || statusCounts['In Progress'] || 0) + (maintenanceCounts.inProgress || maintenanceCounts['In Progress'] || 0);
  const combinedCompleted = (statusCounts.completed || statusCounts.Completed || 0) + (maintenanceCounts.completed || maintenanceCounts.Completed || 0);
  const combinedOverdue = (statusCounts.overdue || statusCounts.Overdue || 0) + (maintenanceCounts.overdue || maintenanceCounts.Overdue || 0);
  const requestStatusOptions = ['Pending', 'Approved', 'In Progress', 'Declined'];
